mapper.update:
MERGE INTO EMP_IMAGE T
USING (
    SELECT #{empNo} AS EMP_NO FROM DUAL
) S
ON (T.EMP_NO = S.EMP_NO AND T.ORDER_NUM = 1)
WHEN MATCHED THEN
    UPDATE SET
        EMP_FILENAME = #{empFilename}
WHEN NOT MATCHED THEN
    INSERT (
        EMP_NO, ORDER_NUM, EMP_FILENAME
    ) VALUES (
        #{empNo}, 1, #{empFilename}
    )

mapper.delete:
DELETE FROM EMP_IMAGE
 WHERE EMP_NO    = #{empNo}
   AND ORDER_NUM = 1
